    if (__builtin_expect(size == 1, 1))
    {
        return static_cast<T>(data[fieldArrayIndex]);
    }

    const FIT_UINT8* const p = data + (fieldArrayIndex * size);

    if constexpr (std::is_integral<T>::value)
    {
        if (size == sizeof(T))
        {
            T rv;
            std::memcpy(&rv, p, sizeof(T));
            return rv;
        }
    }

    if (size == 2)
